window.DIGEST.news.push(...[{"headline": "ElevenLabs Launches Eleven Realtime for Ultra-Fast Voice Agents", "meta": "Explore · News tab · 11 hours ago · News · 543 posts (appeared in News tab center column, not in Today's News sidebar)", "url": "https://x.com/i/trending/2112568261988725183", "summary": "ElevenLabs released Eleven Realtime v1 Mini and v1 Max, end-to-end models combining speech recognition, reasoning, and text-to-speech for natural, quick conversations. Mini handles everyday chats at low cost; Max excels at complex tasks like customer support, scoring 98.8% on spoken reasoning benchmarks with audio output starting in 0.57 seconds. Developers can deploy via ElevenAgents or a Realtime API compatible with OpenAI's protocol, supporting 90+ languages and 17,000 voices for phone lines, websites, etc. (X's Grok X summary, 'Last updated 5 hours ago', captured in prior session and re-used; the /i/trending/2112568261988725183 trend page was not re-opened in this run.)", "posts": [{"id": "2112550784835715229", "url": "https://x.com/ElevenLabs/status/2112550784835715229", "text": "The future of voice AI is one system optimized end-to-end for more natural interactions at lower latency.\n\nEleven Realtime v1 Max scores 98.8% on Big Bench Audio and starts speaking in 0.57s. No model on the Artificial Analysis leaderboard is both faster and more accurate.", "name": "ElevenLabs", "handle": "ElevenLabs", "avatar": "https://pbs.twimg.com/profile_images/2110017247381274625/UlZuSZjC_200x200.png", "likes": 56, "rts": 2, "replies": 4, "views": 7876, "ts": 1792506331, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFJfSeagAEXxRm.jpg?name=orig"}], "quote": null, "reply_to": "2112550782063247521"}], "notes": "Third post (ElevenLabs v1 Max benchmark follow-up, 11h ago) captured this run via from:ElevenLabs search. Full 3-of-3 top-post target now met.", "captured": 1792550214, "post_ids": ["2112550782063247521", "2112563997379592578", "2112550784835715229"]}, {"headline": "Krea 3 Rockets into Top Four on AI Image Editing Benchmarks", "meta": "Explore · Trending · Trending now · News · 824 posts", "url": "https://x.com/i/trending/2112574677205819792", "summary": "Krea 3 launched in mid-October with 'Fast' mode delivering 2K edits in under eight seconds and 'Ultra' mode earning a 1151 Elo rating, fourth on Artificial Analysis and DesignArena leaderboards. It excels in real-world tasks like consistent relighting, pose adjustments, and precise regional edits using bounding boxes or up to six reference images, while keeping character identities and text intact. Priced from $0.03 per 1K image, it's cheaper than rivals and available now on krea.ai, proving small teams can compete at the frontier with features like weight licensing for custom fine-tuning.", "posts": [{"id": "2112570237874810918", "url": "https://x.com/testingcatalog/status/2112570237874810918", "text": "Krea 3 Ultra and Krea 3 Fast landed in the top 5 and 11th spots on the Artificial Analysis image-editing leaderboard!\n\n> Krea 3 Ultra placed 4th with a score of 1151, one point behind Google's Nano Banana 2.1.\n\n> The other four spots in the 5 five are all taken by OpenAI, Google, and MAI models.\n\n> Krea 3 Fast scored 1125, landing in 11th place, topping Nano Banana 2 by one point.\n\nAt the same time, Krea 3 is also 10x faster than GPT Image 2 and 4x faster than Nano Banana Pro, with pricing starting at $0.03 per image at 1K and $0.06 at 2K.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 83, "rts": 2, "replies": 11, "views": 8550, "ts": 1792510969, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112570056815058946/vid/avc1/1280x720/cqKK9JmK4sr3R-Xh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112570056815058946/vid/avc1/3840x2160/nzaHbLrQLzzlXgwH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112570056815058946/img/5zRed5P9p9SJ_Luz.jpg", "dur": 7}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1097, "rts": 143, "replies": 103, "views": 911816, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792517014, "post_ids": ["2112567020353102324", "2112567870702092322", "2112570237874810918"]}, {"headline": "Gradium Open-Sources Compact Phonon TTS Models for Local Devices", "meta": "Explore · Trending · Trending now · News · 208 posts", "url": "https://x.com/i/trending/2112574674672459945", "summary": "Gradium released Phonon, a family of text-to-speech models under 50 million parameters that run locally on devices, supporting English, French, German, Spanish, and Portuguese with strong naturalness and low error rates. They outperform rivals like Kokoro in blind tests, especially in non-English languages, and demo in browsers with 10-millisecond response times. Developers praise the zero-cost, offline setup for apps on everything from Raspberry Pi to mobile, with easy integration via Hugging Face, Ollama, and Rust inference. Co-founder Laurent Mazare says they punch above their weight for quality on any hardware.", "posts": [{"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, {"id": "2112566104745029844", "url": "https://x.com/Diptish09/status/2112566104745029844", "text": "Waiting for AI voice to load… GONE!\n\nPhonon starts speaking in milliseconds, right on your laptop CPU.\n\nThat’s the kind of speed that makes voice AI feel instant.", "name": "Dipti Sharma", "handle": "Diptish09", "avatar": "https://pbs.twimg.com/profile_images/1917200160418930688/hhWz1T4C_200x200.jpg", "likes": 155, "rts": 76, "replies": 2, "views": 32005, "ts": 1792509983, "media": [], "quote": {"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112564851000082633", "url": "https://x.com/neilzegh/status/2112564851000082633", "text": "For a while now, Kokoro has led in terms of naturalness with only 82M parameters. We’re open sourcing 2x smaller models that score higher in naturalness, accuracy and come with voice cloning. The gap in naturalness is particularly striking beyond English as shown by the ELO scores below.", "name": "Neil Zeghidour", "handle": "neilzegh", "avatar": "https://pbs.twimg.com/profile_images/1922791965805903872/0jK1csVd_200x200.jpg", "likes": 170, "rts": 13, "replies": 13, "views": 6043, "ts": 1792509684, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFWiJWWkAEkWIZ.jpg?name=orig"}], "quote": {"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792517014, "post_ids": ["2112563128487514512", "2112566104745029844", "2112564851000082633"]}, {"headline": "Croatian Startup Daytona Hits $1 Billion Valuation with $60 Million Raise", "meta": "Explore · Trending · Trending now · News · 377 posts", "url": "https://x.com/i/trending/2112568258935292315", "summary": "Daytona, founded in 2023 by Ivan Burazin, Goran Draganić, and Vedran Jukić, raised $60M in Series B funding led by FirstMark, reaching a $1B valuation and becoming Croatia's third unicorn. The company builds fast, secure sandboxes for AI agents, spinning up isolated 'computers' in 60 ms to handle unpredictable workloads traditional clouds struggle with. Customers like Meta, Cohere, and Writer fueled 25x revenue growth since January; notable investors include Stripe and Shopify founders plus Qualcomm Ventures. 35-person team, hiring, positioning as the 'Agent Cloud.'", "posts": [{"id": "2112559682720055454", "url": "https://x.com/ivanburazin/status/2112559682720055454", "text": "We just raised a $60M Series B at a $1B valuation to build @daytonaio into the Agent Cloud.\n\n@FirstMarkCap led the round, with all key existing investors and angels doubling down. \n\nWe're also thrilled to welcome the founders of some generational companies aboard, including @patrickc (Stripe), @tobi (Shopify), @AravSrinivas (Perplexity), @BrendanFoody (Mercor), @oliveur (Datadog), @adamdangelo (Quora) and @ericsyuan (Zoom)\n\nWe're a 35-person team. But that's about to change; we're hiring across the board, and we'd love for you to join us.", "name": "Ivan Burazin", "handle": "ivanburazin", "avatar": "https://pbs.twimg.com/profile_images/1549052013178134529/FljtGcgj_200x200.jpg", "likes": 1198, "rts": 163, "replies": 395, "views": 216133, "ts": 1792508452, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112559537509007360/pu/vid/avc1/640x360/TiI17s7RQpkFzSkA.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112559537509007360/pu/vid/avc1/1280x720/dH8u9RF8bHePQeEK.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112559537509007360/pu/img/JhN3sr1O3ldFBVdH.jpg", "dur": 60}], "quote": null, "reply_to": null}, {"id": "2112560532062650398", "url": "https://x.com/daytonaio/status/2112560532062650398", "text": "We just raised a $60M Series B at a $1B valuation to build the Agent Cloud.", "name": "Daytona", "handle": "daytonaio", "avatar": "https://pbs.twimg.com/profile_images/1764766523770494977/NwdtuoVp_200x200.jpg", "likes": 118, "rts": 11, "replies": 9, "views": 5415, "ts": 1792508654, "media": [], "quote": {"id": "2112559682720055454", "url": "https://x.com/ivanburazin/status/2112559682720055454", "text": "We just raised a $60M Series B at a $1B valuation to build @daytonaio into the Agent Cloud.\n\n@FirstMarkCap led the round, with all key existing investors and angels doubling down. \n\nWe're also thrilled to welcome the founders of some generational companies aboard, including @patrickc (Stripe), @tobi (Shopify), @AravSrinivas (Perplexity), @BrendanFoody (Mercor), @oliveur (Datadog), @adamdangelo (Quora) and @ericsyuan (Zoom)\n\nWe're a 35-person team. But that's about to change; we're hiring across the board, and we'd love for you to join us.", "name": "Ivan Burazin", "handle": "ivanburazin", "avatar": "https://pbs.twimg.com/profile_images/1549052013178134529/FljtGcgj_200x200.jpg", "likes": 1198, "rts": 163, "replies": 395, "views": 216133, "ts": 1792508452, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112559537509007360/pu/vid/avc1/640x360/TiI17s7RQpkFzSkA.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112559537509007360/pu/vid/avc1/1280x720/dH8u9RF8bHePQeEK.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112559537509007360/pu/img/JhN3sr1O3ldFBVdH.jpg", "dur": 60}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112560475892515076", "url": "https://x.com/CipcicMarijan/status/2112560475892515076", "text": "Incredibly proud that @daytonaio has raised Series B and joined the unicorn club! 🦄🚀\n\nGrateful to be part of this journey with an amazing team!\nProud to contribute through events and community building worldwide. \n\nAnd trust me, this is just the beginning! Bigger things ahead! 🚀", "name": "Marijan Cipcic", "handle": "CipcicMarijan", "avatar": "https://pbs.twimg.com/profile_images/1986481511437058048/w91Cql0-_200x200.jpg", "likes": 92, "rts": 1, "replies": 23, "views": 1873, "ts": 1792508641, "media": [], "quote": {"id": "2112559682720055454", "url": "https://x.com/ivanburazin/status/2112559682720055454", "text": "We just raised a $60M Series B at a $1B valuation to build @daytonaio into the Agent Cloud.\n\n@FirstMarkCap led the round, with all key existing investors and angels doubling down. \n\nWe're also thrilled to welcome the founders of some generational companies aboard, including @patrickc (Stripe), @tobi (Shopify), @AravSrinivas (Perplexity), @BrendanFoody (Mercor), @oliveur (Datadog), @adamdangelo (Quora) and @ericsyuan (Zoom)\n\nWe're a 35-person team. But that's about to change; we're hiring across the board, and we'd love for you to join us.", "name": "Ivan Burazin", "handle": "ivanburazin", "avatar": "https://pbs.twimg.com/profile_images/1549052013178134529/FljtGcgj_200x200.jpg", "likes": 1198, "rts": 163, "replies": 395, "views": 216103, "ts": 1792508452, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112559537509007360/pu/vid/avc1/640x360/TiI17s7RQpkFzSkA.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112559537509007360/pu/vid/avc1/1280x720/dH8u9RF8bHePQeEK.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112559537509007360/pu/img/JhN3sr1O3ldFBVdH.jpg", "dur": 60}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792517014, "post_ids": ["2112559682720055454", "2112560532062650398", "2112560475892515076"]}, {"headline": "Eka Robotics Raises $150M at $1.45B Valuation for Force-Sensing AI Arms", "meta": "Explore · Trending · Trending now · News · 52 posts", "url": "https://x.com/i/trending/2112574680343154716", "summary": "Cambridge startup Eka Robotics, co-founded by MIT's Pulkit Agrawal and ex-Google DeepMind researcher Tuomas Haarnoja, secured $150M in Series A funding led by a16z and F-Prime Capital, valuing the company at $1.45B. Their Vision-Force-Action model combines visual perception with force feedback, enabling reliable picks at 1,500/hour with >95% success in tests (twice a human's pace). Targets manufacturing/logistics; Agrawal emphasizes balancing generality and performance via reinforcement learning and retries.", "posts": [{"id": "2112564529905221861", "url": "https://x.com/pulkitology/status/2112564529905221861", "text": "@EkaRobotics has raised a $150M Series A.\n\nGenerality v/s Performance is the fundamental tension at the frontier of robotics. Generality without performance is just a prototype. Performance without generality is just a single-purpose tool.\n\nCustomers shouldn’t have to choose. Eka breaks the tradeoff. Powered by our Vision-Force-Action (VFA) model, we deliver the performance and versatility customers need to put robots to work every day.\n\nEka is built on three convictions: \n⚡️Force is the language of manipulation. \n 🚀 Reinforcement learning is how dexterous manipulation scales. \n🎂 System 1—fast, reliable physical execution—is the bottleneck to solve.\n\nWith this funding, we will scale our model and accelerate customer deployments.\n\nGrateful to be building alongside a dream team and investors who share our ambition.", "name": "Pulkit Agrawal", "handle": "pulkitology", "avatar": "https://pbs.twimg.com/profile_images/952619389857153025/Uhr_wfXH_200x200.jpg", "likes": 768, "rts": 81, "replies": 63, "views": 74233, "ts": 1792509608, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112558017560387585/vid/avc1/1280x720/DNbO508h66HSSQW0.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112558017560387585/vid/avc1/1920x1080/sFqUGJOXTFpyLjOs.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112558017560387585/img/dzODOZVG31Ix3Bko.jpg", "dur": 24}], "quote": null, "reply_to": null}, {"id": "2112569769648087279", "url": "https://x.com/a16z/status/2112569769648087279", "text": "We believe solving dexterous manipulation is one of the largest opportunities in robotics. That’s why we're thrilled to lead Eka Robotics’ Series A.\n\nMuch of the world's physical economy still depends on people using their hands, and that work has been hard to automate because the real world is variable.\n\n@EkaRobotics has built a Vision-Force-Action model that combines visual perception with force feedback from its robotic hands. The model, sensing, and hardware are designed together, so the robot can use physical contact itself as information.\n\nIf Eka’s approach works at scale, the implication is profound: robot experience can increasingly scale with compute rather than human labor.\n\nPulkit Agrawal is one of the leading researchers in robot learning and a pioneer in computational sensorimotor learning through work at his Improbable AI Lab at MIT CSAIL. Tuomas Haarnoja co-created a foundational algorithms in modern reinforcement learning at Berkeley and later worked at Google DeepMind training complex humanoid behaviors.\n\nCongrats, @pulkitology, @haarnoja, and the Eka Robotics team!\n\nBy @stuffyokodraws and @RaghuRaghuram", "name": "a16z", "handle": "a16z", "avatar": "https://pbs.twimg.com/profile_images/1919488160125616128/QAZXTMEj_200x200.png", "likes": 173, "rts": 18, "replies": 22, "views": 20309, "ts": 1792510857, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFbAjabAAEJfaa.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112530040193737029", "url": "https://x.com/TechCrunch/status/2112530040193737029", "text": "Eka Robotics may be the first robotic arm that is actually good at picking a wide range of objects up, and it is so smooth and human-like, it is wowing the industry.\nhttps://spr.ly/6011BHT29F", "name": "TechCrunch", "handle": "TechCrunch", "avatar": "https://pbs.twimg.com/profile_images/1096066608034918401/m8wnTWsX_200x200.png", "likes": 33, "rts": 8, "replies": 11, "views": 17144, "ts": 1792501385, "media": [], "quote": null, "reply_to": null}], "captured": 1792517014, "post_ids": ["2112564529905221861", "2112569769648087279", "2112530040193737029"]}, {"headline": "Bria AI Launches Fibo 2.0, Tops Image Editing Benchmarks", "meta": "Today's News · Trending now · News · 114 posts", "url": "https://x.com/i/trending/2112593109930696971", "summary": "The 8B-parameter Bria Fibo 2.0 outscores 33 closed models on Artificial Analysis's AA-Image-Editing v2.1 leaderboard (Elo 1087). Trained on licensed data with JSON-native controls; Dev and Edit Turbo variants on Hugging Face, fal and Bria API at $32 per 1,000 images.", "posts": [{"id": "2112593696957022591", "url": "https://x.com/aisearchio/status/2112593696957022591", "text": "AI never sleeps. I just finished the video on MOSS, and now we have a new image EDIT model, Fibo 2.0.\n\nApparently it's the #1 open image edit model.\n\nTesting it out today.\n\nhttps://huggingface.co/briaai/Fibo-2.0-dev", "name": "AI Search", "handle": "aisearchio", "avatar": "https://pbs.twimg.com/profile_images/1766883795150479360/uu_KeDD1_200x200.jpg", "likes": 436, "rts": 25, "replies": 18, "views": 15043, "ts": 1792516562, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFwf1MaYAA9AVO.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112573259606884640", "url": "https://x.com/ArtificialAnlys/status/2112573259606884640", "text": "Fibo 2.0 from @bria_ai_ is the #1 open weights model on AA-Image-Editing v2.1 and statistically tied with Qwen-Image-2.1 for the lead on AA-Image-T2I v2.1, a large step up from Bria's first-generation Fibo models on both leaderboards\n\nFibo 2.0 is Bria’s new 8B parameter open weights image model. The weights are released under a non-commercial license, which requires a separate agreement with Bria for commercial use. Bria released two sets of open weights: Fibo 2.0 Dev for Text to Image, and Fibo 2.0 Edit Turbo, a faster distilled model, for Image Editing. We benchmarked Fibo 2.0 through the Bria API at its default settings.\n\nFibo 2.0 is level with Qwen-Image-2.1 as the leading open weights model on both AA-Image-Editing v2.1 and AA-Image-T2I v2.1. It is a large step up from Bria's first-generation Fibo models on both leaderboards: it scores higher on every editing action and Text to Image capability we measure, with the biggest gains in Text or Symbol Edits, Text Rendering and Layout.\n\nFibo 2.0 costs $32 per 1k images on the Bria API. Luma UNI 1 Max ($100 per 1k images) and Qwen Image 2.0 Pro ($75) cost more and score slightly lower on both leaderboards, while Grok Imagine Image Quality scores about the same at $50. It is available through the Bria API and fal, with open weights on Hugging Face.\n\nCongratulations to @bria_ai_ on the release!\n\nSee below for our analysis and example outputs of Fibo 2.0 on AA-Image-Editing v2.1 and AA-Image-T2I v2.1 🧵", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 201, "rts": 18, "replies": 18, "views": 18912, "ts": 1792511689, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVFYE-EbsAAYqdV.mp4", "hd": "https://video.twimg.com/tweet_video/HVFYE-EbsAAYqdV.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVFYE-EbsAAYqdV.jpg", "dur": 0}], "quote": null, "reply_to": null}, {"id": "2112562029336608819", "url": "https://x.com/fal/status/2112562029336608819", "text": "Bria Fibo 2.0 from @bria_ai_ is live on fal.\n\nThe #1 open-weight image editing model on Artificial Analysis, with text-to-image generation and targeted editing. Trained only on licensed data, with clear commercial rights.\n\n- Image editing with up to four input images\n- Background swaps, product restaging and lighting changes\n- Text-to-image generation for reasoning-heavy prompts", "name": "fal", "handle": "fal", "avatar": "https://pbs.twimg.com/profile_images/1836456388937285632/OFsq77aX_200x200.jpg", "likes": 162, "rts": 15, "replies": 19, "views": 11276, "ts": 1792509011, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112561964220100608/pu/vid/avc1/634x360/vC-o_Hffe3yKvJbH.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112561964220100608/pu/vid/avc1/1270x720/E7RmTcP-UZ_yex2J.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112561964220100608/pu/img/4l8nJ7H1fVEw5Gjr.jpg", "dur": 51}], "quote": null, "reply_to": null}], "captured": 1792522690, "post_ids": ["2112593696957022591", "2112573259606884640", "2112562029336608819"]}, {"headline": "Mistral AI Launches Voxtral 3 for Natural Voice Agents", "meta": "Today's News · Trending now · News · 253 posts", "url": "https://x.com/i/trending/2112593114783461809", "summary": "Voxtral 3: speech-to-text, text-to-speech and a voice agent SDK for real-time conversation in 50+ languages, with Pro Voice cloning, EU or self-hosted deployment, $13 per million characters.", "posts": [{"id": "2112589831641710797", "url": "https://x.com/arthurmensch/status/2112589831641710797", "text": "We've just released a comprehensive suite of state-of-the-art voice models https://mistral.ai/news/voxtral-3/. Voice will be the most important interface to AI systems, and we deploy voice models physically close to reasoning models", "name": "Arthur Mensch", "handle": "arthurmensch", "avatar": "https://pbs.twimg.com/profile_images/1887904839931248640/2_rjHToC_200x200.jpg", "likes": 807, "rts": 105, "replies": 39, "views": 18989, "ts": 1792515640, "media": [], "quote": null, "reply_to": null}, {"id": "2112591060052656585", "url": "https://x.com/GuillaumeLample/status/2112591060052656585", "text": "🎙️ Introducing Voxtral 3 !\n\nA new family of SOTA speech models:\nASR: Mini & Small for batch transcription, plus real-time streaming\nTTS: expressive, multilingual speech, batch + streaming\nVoice agent SDK: low-latency conversations + tool calling\n\nAvailable via API or on your own infrastructure !", "name": "Guillaume Lample @ NeurIPS 2024", "handle": "GuillaumeLample", "avatar": "https://pbs.twimg.com/profile_images/1204529916026458112/_kcTUp8s_200x200.jpg", "likes": 328, "rts": 40, "replies": 15, "views": 13739, "ts": 1792515933, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFtKUUaAAACvhz.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFtWCBaMAAFrZG.jpg?name=orig"}], "quote": {"id": "2112574615318876178", "url": "https://x.com/MistralAI/status/2112574615318876178", "text": "Introducing Voxtral 3: state-of-the-art Transcribe and Speech models powering Mistral’s new voice agents API. 🧵", "name": "Mistral AI", "handle": "MistralAI", "avatar": "https://pbs.twimg.com/profile_images/1996905418065375232/mzwynOLB_200x200.jpg", "likes": 2694, "rts": 326, "replies": 183, "views": 170539, "ts": 1792512012, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112572094693220352/vid/avc1/1280x720/rgbuEnf2km5NbUak.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112572094693220352/vid/avc1/3840x2160/7Y5bCsXT49_OdFeI.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112572094693220352/img/jKD0R5NWaGjhvRcX.jpg", "dur": 128}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792522690, "post_ids": ["2112574615318876178", "2112589831641710797", "2112591060052656585"]}, {"headline": "AI Designs First Viruses Used in Human to Fight Superbug", "meta": "Today's News · Trending now · News · 319 posts", "url": "https://x.com/i/trending/2112587396113989744", "summary": "Biotech startup Radical Numerics used its Omnii-1 AI model to design bacteriophages targeting a patient's tough E. coli infection. After lab success, doctors administered the cocktail under FDA-approved compassionate use, marking the first known clinical application of AI-generated phages. CEO Eric Nguyen called it a world first, with the process slashing design time from months to weeks and offering hope against rising superbugs. The company plans peer-reviewed publication while stressing this single case needs more testing for safety and effectiveness.", "posts": [{"id": "2112547887246938471", "url": "https://x.com/Polymarket/status/2112547887246938471", "text": "JUST IN: Biotech startup reveals it has treated a human patient with AI-designed viruses for the first time, targeting an antibiotic-resistant E. coli infection.", "name": "Polymarket", "handle": "Polymarket", "avatar": "https://pbs.twimg.com/profile_images/2005664281002491904/bz2ZO_nU_200x200.jpg", "likes": 1610, "rts": 157, "replies": 58, "views": 115925, "ts": 1792505640, "media": [], "quote": null, "reply_to": null}, {"id": "2112580926651904379", "url": "https://x.com/exnx/status/2112580926651904379", "text": "Introducing Omnii-1, our most powerful genome language model, and a major step toward general biological intelligence\n\nIn a world first, Omnii-1 designed the first AI-generated bacteriophages to be administered to a human patient with an antibiotic-resistant infection under compassionate use", "name": "Eric Nguyen", "handle": "exnx", "avatar": "https://pbs.twimg.com/profile_images/1640862340517335040/qcpMIN_b_200x200.jpg", "likes": 925, "rts": 163, "replies": 95, "views": 460868, "ts": 1792513517, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112578540013330432/vid/avc1/1280x720/o7F7SW5uTq0n6Cki.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112578540013330432/vid/avc1/1920x1080/PQ3lBUGHdIKOCD3U.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112578540013330432/img/iIkujuAjkAiQkxwh.jpg", "dur": 155}], "quote": null, "reply_to": null}, {"id": "2112567434788180241", "url": "https://x.com/MTSlive/status/2112567434788180241", "text": "SITUATION DETECTED: Bio startup Radical Numerics has used AI-generated viruses - bacteriophages designed by its multimodal genome model Omnii-1 - to treat an antibiotic-resistant infection in the first clinical use of AI-generated phages on a human patient.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 893, "rts": 70, "replies": 9, "views": 35997, "ts": 1792510300, "media": [], "quote": null, "reply_to": null}], "source": "Today's News sidebar / News tab; captured this run", "captured": 1792518142, "post_ids": ["2112547887246938471", "2112580926651904379", "2112567434788180241"]}, {"headline": "Google's Gemini 4 Argon Generates Stunning 3D Worlds from Simple Prompts", "meta": "Today's News · News · 1 day ago · 8.1K posts", "url": "https://x.com/i/trending/2112258803760816594", "summary": "Google DeepMind showcased Gemini 4 Argon creating interactive 3D experiences (playable wizard chess, fur physics engine, racing track from a desk photo) from simple prompts inside Antigravity. Handles up to 1M tokens for coding/science/design, tops Vals Index and DeepSWE benchmarks; API pricing $2/M input tokens and $10/M output through November. Users praise creative power but note heavy token burn; follow-up Gemini 4 Carbon reportedly in testing.", "posts": [{"id": "2112521983670055196", "url": "https://x.com/yadavji_codes/status/2112521983670055196", "text": "Guys, try not to mess with Argon 4 😭", "name": "Sudhanshu", "handle": "yadavji_codes", "avatar": "https://pbs.twimg.com/profile_images/2031473888555843584/Ct6Lzm_s_200x200.jpg", "likes": 11959, "rts": 438, "replies": 253, "views": 336946, "ts": 1792499464, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEvizwaYAE7k2i.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112767157746688480", "url": "https://x.com/OfficialLoganK/status/2112767157746688480", "text": "In just the first 72 hours since Gemini 4 Argon launched, we processed ~25 trillion tokens, the demand for intelligence is incredible and still under appreciated!", "name": "Logan Kilpatrick", "handle": "OfficialLoganK", "avatar": "https://pbs.twimg.com/profile_images/1943787288955084800/QOl7OJMc_200x200.jpg", "likes": 646, "rts": 24, "replies": 114, "views": 23842, "ts": 1792557918, "media": [], "quote": null, "reply_to": null}, {"id": "2112648189656616999", "url": "https://x.com/sundarpichai/status/2112648189656616999", "text": "Sound on!", "name": "Sundar Pichai", "handle": "sundarpichai", "avatar": "https://pbs.twimg.com/profile_images/2051799620062429184/AL8CoAUG_200x200.jpg", "likes": 3676, "rts": 282, "replies": 160, "views": 220058, "ts": 1792529554, "media": [], "quote": {"id": "2112557925264752930", "url": "https://x.com/GoogleDeepMind/status/2112557925264752930", "text": "Gemini 4 Argon built a 3D periodic table synced to Tom Lehrer’s song, “The Elements.”\n\nCreated in @Antigravity, it animates orbiting electrons, atomic data, and light spectra.", "name": "Google DeepMind", "handle": "GoogleDeepMind", "avatar": "https://pbs.twimg.com/profile_images/1695024885070737408/-M-HSH5P_200x200.jpg", "likes": 2994, "rts": 333, "replies": 231, "views": 312848, "ts": 1792508033, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112556446218862593/vid/avc1/1280x720/Jg_oHGtDOkoBttrU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112556446218862593/vid/avc1/1920x1080/pY7aXhWMcWehJljh.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112556446218862593/img/vm7Hadu5pWswOhr9.jpg", "dur": 88}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792561211, "post_ids": ["2112521983670055196", "2112767157746688480", "2112648189656616999"]}, {"headline": "Vyb AI Tackles Generic Design Complaints with Brand-First Tools", "meta": "Today's News · Trending now · News · 526 posts", "url": "https://x.com/i/trending/2112598867225059778", "summary": "Vyb (Coco Labs, Anusha Ramesh) extracts brand assets from a website URL into editable layers with Figma export; private beta.", "posts": [{"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1822098, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, {"id": "2112585216300863603", "url": "https://x.com/DocumentingAGI/status/2112585216300863603", "text": "CocoAI Labs (ex-Google Brain/DeepMind) launches Vyb, an AI design model that constructs editable layered designs instead of flat generic images.\n\nIt extracts exact logos, fonts, and colors from a website, places real product photos without redrawing them, and exports to Figma.\n\nSpecialized models that preserve user assets and produce structured, editable output are a practical step beyond current image generators.", "name": "Documenting AGI", "handle": "DocumentingAGI", "avatar": "https://pbs.twimg.com/profile_images/2042920180825886721/2fa6dY9O_200x200.jpg", "likes": 225, "rts": 15, "replies": 9, "views": 24477, "ts": 1792514540, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112584557740318720/vid/avc1/1280x720/zIZUhxn0xJrwXNUL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112584557740318720/vid/avc1/1920x1080/i-kvsr8N4s_bL_WJ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112584557740318720/img/nNX_t_atG6oinqNN.jpg", "dur": 12}], "quote": {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1823711, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792522690, "post_ids": ["2112581900779012503", "2112585216300863603"]}, {"headline": "METR Review Challenges Anthropic's AI Misalignment Risk Assessment", "meta": "Today's News · Trending now · News · 103 posts", "url": "https://x.com/i/trending/2112598867820654636", "summary": "METR's review of Anthropic's August 2026 Risk Report agrees on thoughtfulness but disputes covert-capability benchmarks as weak proxies and urges more transparency on monitoring.", "posts": [{"id": "2112562150313283595", "url": "https://x.com/METR_Evals/status/2112562150313283595", "text": "We reviewed a nonpublic version of the “Misalignment in high-stakes settings” section in Anthropic’s Aug 2026 Risk Report. We agree that risk of catastrophic harm from covered models’ misalignment is low. However, we note several significant disagreements with their analysis.", "name": "METR", "handle": "METR_Evals", "avatar": "https://pbs.twimg.com/profile_images/2021827383431757824/AeVvT0rU_200x200.jpg", "likes": 796, "rts": 95, "replies": 14, "views": 124745, "ts": 1792509040, "media": [], "quote": {"id": "2088324824863236248", "url": "https://x.com/AnthropicAI/status/2088324824863236248", "text": "As part of our Responsible Scaling Policy, we publish regular Risk Reports. These share detailed information on the risks of our systems and how prepared we are to address them.\n\nOur second Risk Report is now available: https://www.anthropic.com/aug-2026-risk-report", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 2924, "rts": 281, "replies": 331, "views": 4386346, "ts": 1786730412, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112581339216273813", "url": "https://x.com/So8res/status/2112581339216273813", "text": "You worry that METR is not independent enough because its employees have some social connections to Anthropic employees.\n\nI worry that METR is not independent enough because they have to carefully avoid ticking Anthropic off, lest their access be revoked.\n\nWe are not the same.", "name": "Nate Soares ⏹️", "handle": "So8res", "avatar": "https://pbs.twimg.com/profile_images/1935185891863273472/2RB6s6TS_200x200.jpg", "likes": 405, "rts": 21, "replies": 19, "views": 9599, "ts": 1792513615, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFlaPJboAA8iu_.jpg?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792522690, "post_ids": ["2112562150313283595", "2112581339216273813"]}, {"headline": "DeepSeek V4", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=%22DeepSeek%20V4%22&src=trend_click&vertical=trends", "summary": "DeepSeek V4.1 Flash 1017 trending; DesignArena projects it #3 among open-weight models.", "posts": [{"id": "2112551437314183171", "url": "https://x.com/AskVenice/status/2112551437314183171", "text": "In Venice Chat: DeepSeek V4.1 Flash.\n\nPick it in the model menu, drop in your sensitive files, and ask. Ten receipts. One expense table. $934.50.\n\nIt runs privately. Nothing you send is stored.", "name": "Venice", "handle": "AskVenice", "avatar": "https://pbs.twimg.com/profile_images/2063006544615120896/yzx4UbK7_200x200.png", "likes": 140, "rts": 11, "replies": 13, "views": 9339, "ts": 1792506486, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112551413259931648/vid/avc1/1280x720/iiuGqUlWrx0VRn8K.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112551413259931648/vid/avc1/1920x1080/mFAWrL68jJjjRR2y.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112551413259931648/img/sU6KY6qxGS9aN23O.jpg", "dur": 30}], "quote": null, "reply_to": null}], "captured": 1792522690, "post_ids": ["2112551437314183171", "2112330696790556999"]}, {"headline": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "meta": "Today's News · News · 228 posts", "url": "https://x.com/i/trending/2112616541284090282", "summary": "OpenAI has bought Orchestra Bio, a platform that coordinates biopharma teams on tasks like monitoring studies and spotting delays. The company will merge it with its Rosalind AI tools, including GPT-Rosalind for biology and chemistry, to link discoveries directly to decisions and get treatments to patients faster. This builds on partnerships with Novo Nordisk and Moderna, following similar steps by rival Anthropic. Observers see it as pairing AI discovery with smooth operations in life sciences.", "posts": [{"id": "2112607347688583586", "url": "https://x.com/OpenAI/status/2112607347688583586", "text": "We’ve acquired Orchestra Bio, a platform that helps biopharma teams coordinate the complex process of drug development.\n\nTogether, we’ll build on Rosalind, our AI models and tools for life sciences research, to streamline those operations and help new treatments reach patients sooner.\n\nWelcome @ashokaraj_ and team!\n\nhttps://openai.com/index/openai-to-acquire-orchestra-bio/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 5905, "rts": 522, "replies": 371, "views": 545241, "ts": 1792519816, "media": [], "quote": null, "reply_to": null}, {"id": "2112611383766663412", "url": "https://x.com/AndrewCurran_/status/2112611383766663412", "text": "Drug discovery, new disease cures, advancements in pharma and biomedicine. Along with direct dividends or shares - as is currently being discussed - these are the only viable ways to turn public sentiment around. The big push will start to happen in 2027.", "name": "Andrew Curran", "handle": "AndrewCurran_", "avatar": "https://pbs.twimg.com/profile_images/1596945208058744833/_X3LT7fb_200x200.jpg", "likes": 579, "rts": 51, "replies": 31, "views": 33224, "ts": 1792520778, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGA23UaUAA-4yC.jpg?name=orig"}], "quote": {"id": "2112607347688583586", "url": "https://x.com/OpenAI/status/2112607347688583586", "text": "We’ve acquired Orchestra Bio, a platform that helps biopharma teams coordinate the complex process of drug development.\n\nTogether, we’ll build on Rosalind, our AI models and tools for life sciences research, to streamline those operations and help new treatments reach patients sooner.\n\nWelcome @ashokaraj_ and team!\n\nhttps://openai.com/index/openai-to-acquire-orchestra-bio/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 5905, "rts": 522, "replies": 371, "views": 545241, "ts": 1792519816, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792523701, "post_ids": ["2112607347688583586", "2112611383766663412"]}, {"headline": "Perplexity Launches Fully Local AI Agent on Macs", "meta": "Today's News · 8 hours ago · News · 869 posts (fresher 9 hours ago on center column at reload)", "url": "https://x.com/i/trending/2112604711291400455", "summary": "RECOVER_FROM_PRIOR_SESSION_ONLY — X's Grok summary was captured in the prior session but was not re-read in this run. The trend was surfaced in the Today's News sidebar (news_sidebar_article_QWlUcmVuZDoyMTEyNjA0NzExMjkxNDAwNDU1) and not reopened here. Re-capture recommended on next fire by opening https://x.com/i/trending/2112604711291400455 and reading the 'Summary of this trend' / 'What's happening' block.", "posts": [{"id": "2112583333825950207", "url": "https://x.com/AravSrinivas/status/2112583333825950207", "text": "You can now run Perplexity Computer fully local on your Mac with no cloud based inference, without WiFi too. Enjoy!", "name": "Aravind Srinivas", "handle": "AravSrinivas", "avatar": "https://pbs.twimg.com/profile_images/2099903483457703936/U-W6QQk__200x200.jpg", "likes": 2049, "rts": 124, "replies": 138, "views": 147367, "ts": 1792514091, "media": [], "quote": {"id": "2112571597798461920", "url": "https://x.com/perplexity_ai/status/2112571597798461920", "text": "Perplexity Computer can now run fully local on your Mac.\n\nWork with your native Mac apps and local files, and run tasks without sending sensitive data to the cloud. The model and the agent both run on your Mac.\n\nAvailable now in the Perplexity Mac app.", "name": "Perplexity", "handle": "perplexity_ai", "avatar": "https://pbs.twimg.com/profile_images/2009310641165660160/XArF3_Ib_200x200.jpg", "likes": 1424, "rts": 128, "replies": 132, "views": 225211, "ts": 1792511293, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1280x720/ShXKzcJ5aZU2oEqH.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1920x1080/-Cm77YMLPTK8ejoZ.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112571479745495040/img/6agUzZjpfbZMBBOA.jpg", "dur": 69}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112571597798461920", "url": "https://x.com/perplexity_ai/status/2112571597798461920", "text": "Perplexity Computer can now run fully local on your Mac.\n\nWork with your native Mac apps and local files, and run tasks without sending sensitive data to the cloud. The model and the agent both run on your Mac.\n\nAvailable now in the Perplexity Mac app.", "name": "Perplexity", "handle": "perplexity_ai", "avatar": "https://pbs.twimg.com/profile_images/2009310641165660160/XArF3_Ib_200x200.jpg", "likes": 1424, "rts": 128, "replies": 132, "views": 225211, "ts": 1792511293, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1280x720/ShXKzcJ5aZU2oEqH.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1920x1080/-Cm77YMLPTK8ejoZ.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112571479745495040/img/6agUzZjpfbZMBBOA.jpg", "dur": 69}], "quote": null, "reply_to": null}], "notes": "Only 2 of 3 top-post status URLs captured (third still needed — e.g. a @testingcatalog or @engadget status URL previously visible on the trend page). Summary not re-verified in this run.", "captured": 1792550214, "post_ids": ["2112583333825950207", "2112571597798461920"]}, {"headline": "DeepSeek open-sources DeepInfer inference framework, powers DeepSeek-V4.1-Flash", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=DeepSeek&src=trend_click&vertical=trends", "summary": "", "posts": [{"id": "2112627168861892882", "url": "https://x.com/MTSlive/status/2112627168861892882", "text": "SITUATION EXPLAINED: DeepSeek just open-sourced the engine that runs its AI, something OpenAI and Anthropic haven't done.\n\n• DeepInfer powers DeepSeek V4.1 Flash, which costs $0.30 per million input tokens and $1.20 per million output, and it's now open source under Apache 2.0\n• Inference is running a trained model, and serving a 552B-parameter one fast and cheap to millions of users is one of AI's hardest engineering problems\n• It spreads users, long prompts, and expert sub-networks across GPUs, and uses speculative decoding, where a small model guesses ahead and the big one checks\n• It only runs on Nvidia Blackwell GPUs and Huawei Ascend 950 chips, so it's built for data centers, not home rigs\n• It still leaves out the KV cache system and prefill/decode disaggregation, so it's not a full serving stack\n\n@theojaffee: \"DeepSeek open sources almost everything. It's really incredible. They release their model weights. They write papers explaining in detail their model architecture. They put out GitHub repos with their inference framework. DeepSeek really cares about fully open AGI in a way that other companies don't.\"", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 57, "rts": 7, "replies": 2, "views": 6171, "ts": 1792524542, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112625434680758272/vid/avc1/640x360/vRUdLgo5Qv8CP0Fy.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112625434680758272/vid/avc1/1280x720/iDhu1gO1dNlkKDvA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112625434680758272/img/LncNlUuo4Lg8jPf4.jpg", "dur": 695}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792547114, "post_ids": ["2112476496283775135", "2112627168861892882", "2112471106426900677"]}, {"headline": "Elon Musk Discusses AI Risks, Wealth, and a Money-Free Future", "meta": "Explore · Trending · News · 1.8K posts", "url": "https://x.com/i/trending/2112604714332250325", "summary": "In the debut episode of 'The Builders' podcast released October 20, Musk explained his fortune will mostly fund multi-planetary life, sustainable energy, and space expansion after taxes. He predicted a post-AI world where money fades, replaced by measures like energy and mass, while superintelligent AI with robots could add $30 trillion yearly to Earth's economy. Musk admitted trying to slow AI but accelerating it instead, warning humans may lose control to digital minds a million times smarter—hoping they stay kind.", "posts": [{"id": "2112599662192714215", "url": "https://x.com/WatcherGuru/status/2112599662192714215", "text": "JUST IN: Elon Musk says money will become \"irrelevant\" in the future, with energy and resources becoming the new measures of wealth.", "name": "Watcher.Guru", "handle": "WatcherGuru", "avatar": "https://pbs.twimg.com/profile_images/1641221212578754562/DfiC0KW2_200x200.png", "likes": 9083, "rts": 909, "replies": 1151, "views": 870796, "ts": 1792517984, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVF2MXBXcAADJKr.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVF2MWZXgAAT1m1.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112551927649018058", "url": "https://x.com/SawyerMerritt/status/2112551927649018058", "text": "Elon Musk in new interview with Walter Isaacson on the wealth he's created:\n\n\"A fundamental misunderstanding of economics arises because of conflating resource allocation and consumption; I've created. My so-called wealth is simply a percentage ownership in SpaceX and Tesla. And this is going to be taxed quite heavily, and there's not some magical way to avoid taxes. If there were I would know about it. At the end of the day, this will get whittled down, and a few generations from now, if money still matters, which I don't think it will, my descendants would have a tiny fraction of what I have.\"", "name": "Sawyer Merritt", "handle": "SawyerMerritt", "avatar": "https://pbs.twimg.com/profile_images/1837744842715082752/xH9vYixL_200x200.jpg", "likes": 3053, "rts": 359, "replies": 204, "views": 3126536, "ts": 1792506603, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112550486775574528/vid/avc1/720x740/IVY-zfHHYhRmL9g6.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112550486775574528/vid/avc1/1048x1080/ZUgkMG4w60plxaPE.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112550486775574528/img/vJQOpt-2OGMjqNBW.jpg", "dur": 97}], "quote": null, "reply_to": null}, {"id": "2112588436846911907", "url": "https://x.com/cb_doge/status/2112588436846911907", "text": "BREAKING: Elon Musk says money will become irrelevant and future currency will be measured in power, mass and energy.\n\n“I think currency will be measured in fundamental physics metrics like, you know, power, like wattage and tonnage, mass and energy.”", "name": "DogeDesigner", "handle": "cb_doge", "avatar": "https://pbs.twimg.com/profile_images/1498070100393754625/C2V-fbll_200x200.jpg", "likes": 2357, "rts": 384, "replies": 261, "views": 576479, "ts": 1792515307, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112588200124510209/vid/avc1/1280x720/fbH3yXW-3G3eR0pM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112588200124510209/vid/avc1/1920x1080/Ba8KjUKwiuRecQ9F.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112588200124510209/img/knVRjKgwnSmZEInn.jpg", "dur": 224}], "quote": null, "reply_to": null}], "scope_note": "AI-frontier/safety-adjacent via the AI-risks framing, but substantive focus is on Musk's wealth/money-fading speculation; borderline keep per user scope.", "captured": 1792523701, "post_ids": ["2112599662192714215", "2112551927649018058", "2112588436846911907"]}, {"headline": "Ornith-1.5-122B frontier MoE model launch", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=Ornith-1.5-122B&src=trend_click&vertical=trends", "summary": "Ornith announced open-weight Ornith-1.5-122B MoE, strong and fast, runs on a single DGX card, on Ollama.", "posts": [{"id": "2112565065958449435", "url": "https://x.com/ollama/status/2112565065958449435", "text": "Ornith 1.5 122B is available on Ollama! Run it all locally on your device. \n\nollama run ornith-1.5:122b", "name": "ollama", "handle": "ollama", "avatar": "https://pbs.twimg.com/profile_images/2045273960666071040/rCjCIwiC_200x200.jpg", "likes": 311, "rts": 28, "replies": 24, "views": 23799, "ts": 1792509735, "media": [], "quote": {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086790, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792545066, "post_ids": ["2112553477457268799", "2112565065958449435"]}, {"headline": "TypeScript", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=TypeScript&src=trend_click&vertical=trends", "summary": null, "summary_note": "TypeScript is a keyword trend (Technology · Trending), not a news story — X opens a search results page with no Grok summary blurb. Top results center on TypeScript 7.1 Beta launch and dev-tool news.", "posts": [{"id": "2112610990202507582", "url": "https://x.com/typescript/status/2112610990202507582", "text": "TypeScript 7.1 Beta is now available! Now with a preview API, content mapper support, new features, and some great optimizations. Give it a try and give us some feedback! https://devblogs.microsoft.com/typescript/announcing-typescript-7-1-beta/", "name": "TypeScript", "handle": "typescript", "avatar": "https://pbs.twimg.com/profile_images/1648471227416346625/v84A9gXA_200x200.png", "likes": 994, "rts": 125, "replies": 27, "views": 72083, "ts": 1792520685, "media": [], "quote": null, "reply_to": null}, {"id": "2112644617141371061", "url": "https://x.com/cline/status/2112644617141371061", "text": "Use the Goal plugin in Cline Desktop to keep Cline working until the task is verified complete.\n\nCustomize > Marketplace > Plugins > Install 'Goal' > use /goal\n\nPlugins are TypeScript files that extend Cline's capabilities with:\n- Slash commands\n- Custom tools\n- Lifecycle hooks (beforeTool, afterRun, etc.)\n- Dynamic rules\n\nThe Goal plugin adds a /goal slash command and an afterRun hook that nudges Cline to verify its work, and only when verified complete can it call the plugin's custom mark_goal_complete tool to finish the task.", "name": "Cline", "handle": "cline", "avatar": "https://pbs.twimg.com/profile_images/2100371495658946560/pKjt1-8w_200x200.png", "likes": 62, "rts": 4, "replies": 8, "views": 4138, "ts": 1792528702, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112643720885772289/vid/avc1/1152x720/o7K8tNBVSeNiyl3s.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112643720885772289/vid/avc1/1920x1200/NMI4gESesAIDByVL.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112643720885772289/img/snGi89hJ6QKc9jqZ.jpg", "dur": 18}], "quote": null, "reply_to": null}, {"id": "2112531443591020965", "url": "https://x.com/voidzerodev/status/2112531443591020965", "text": "Introducing tsrs: a Rust port of the TypeScript compiler 🦀\n\nWe are not forking TypeScript!\n\n◆ In close collaborating with the TypeScript team\n◆ Up to 8x faster than TS 7.0 & ~70% less memory\n◆ Runs in WASM, so it works in your browser & on Workers\n◆ Soon part of the Oxc toolchain\n\nnpx tsrs\n\nhttps://blog.cloudflare.com/typescript-rust-port%20%20/", "name": "VoidZero", "handle": "voidzerodev", "avatar": "https://pbs.twimg.com/profile_images/2011008157888159744/bTvdh1Nd_200x200.jpg", "likes": 4329, "rts": 467, "replies": 129, "views": 460890, "ts": 1792501719, "media": [], "quote": null, "reply_to": null}], "captured": 1792559277, "post_ids": ["2112610990202507582", "2112644617141371061", "2112531443591020965"]}, {"headline": "Gradium Open-Sources Phonon: Sub-50M On-Device TTS Models Under Apache 2.0", "meta": "Explore · Trending · Technology · Trending · Apache 2.0", "url": "https://x.com/search?q=Apache+2.0&src=trend_click&vertical=trends", "summary": "The Apache 2.0 keyword trend is led by Gradium (@GradiumAI, 3h ago) open-sourcing Phonon, a suite of text-to-speech models under 50M parameters for on-device speech. Lead post: 'A new frontier for on-device speech. We're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date. Phonon-31m is available under Apache 2.0.' Link: gradium.ai/phonon. Stats: 80 replies, 205 reposts, 766 likes, ~87,678 views. The trend's second post, Ruben (@rdominguezibar, 18h ago), reports KingKong (a Beijing servos/encoders company) open-sourced under Apache 2.0 the software that teaches its crab robot 'Jumper' (22 joints, 1.8 kg) to move, on GitHub, shipping a CLAUDE.md to be opened in a coding agent. A third top post, Respan (@RespanAI, 2h ago), announced 'Respan OSS Gateway: the last AI gateway you ever need' connecting LLMs, images, video, realtime voice, and MCP tools like web search and long-term memory through one endpoint, each as a plugin. A fourth notable mention: Dean W. Perkins (@deanwperkins, 2h ago) noted a 31M-param TTS model (Phonon) now runs inside a browser extension — highlight text, hit Read, speaks it back word by word, no API key, no GPU, no internet round-trip, Apache 2.0. Note: keyword trend chip → search feed; summary built from lead posts. Kept on Gradium Phonon (AI creative tool / on-device / open-source TTS).", "posts": [{"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189182, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, {"id": "2112589739752837309", "url": "https://x.com/RespanAI/status/2112589739752837309", "text": "Respan OSS Gateway: the last AI gateway you ever need.\n\nBecause it can connect anything: LLMs, images, video, realtime voice, and MCP tools like web search and long-term memory, all through one endpoint. Each one is just a plugin you switch on.\n\nAgainst LiteLLM on the same machine:\n - 0.08 ms vs 5.9 ms added latency (78x less)\n - 61,062 vs 1,348 requests/s with 50 in flight (45x more; LiteLLM on 14 workers)\n - 33 MB vs 494 MB memory (15x less; LiteLLM on 1 worker)\n\nFully written in Rust. MIT/Apache-2.0.", "name": "Respan", "handle": "RespanAI", "avatar": "https://pbs.twimg.com/profile_images/2027070589756940288/1tWZSpNu_200x200.jpg", "likes": 129, "rts": 18, "replies": 17, "views": 10341, "ts": 1792515618, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112589708589158400/vid/avc1/1280x720/Vcevcs1-ZMZLV7oo.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112589708589158400/vid/avc1/1920x1080/o7SYrt6EbEVRDm_V.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112589708589158400/img/BRkz-jytt9YRMCOW.jpg", "dur": 30}], "quote": null, "reply_to": null}], "captured": 1792523701, "post_ids": ["2112563128487514512", "2112342171118358679", "2112589739752837309"]}, {"headline": "Beacon Brings Memory Across AI Coding Tools with $5.5M Seed", "meta": "Today's News · Trending now · 743 posts", "url": "https://x.com/i/trending/2112622379822452799", "summary": "Asymptote Labs launched Beacon, an open-source memory layer recording prompts, edits and debugging from Claude Code and Cursor into reusable skills across 20+ agent systems; $5.5M seed led by Tower Research Ventures.", "posts": [{"id": "2112552451547001218", "url": "https://x.com/jqdsouza/status/2112552451547001218", "text": "We’re betting our $5.5M seed round that the next leap in AI coding won’t come from OpenAI or Anthropic.\n\nIt’ll come from a new feedback loop that learns from you.\n\nIntroducing Beacon: open-source, self-improving memory for coding agents.\n\nYour sessions capture how you debug and solve problems. Today, that context gets lost and you have to re-explain things every time you switch tools.\n\nBeacon continuously distills your sessions into reusable skills across Claude Code, Cursor, Codex, and 20+ harnesses, so your next agent can learn from the last.\n\nBeacon is free and OSS 🌟 http://github.com/Asymptote-Labs/agent-beacon\n\nWhy should the frontier labs be the only ones winning with your sessions?\n\nYou already did the work. Now let your coding agents learn from you.", "name": "Justin D'Souza", "handle": "jqdsouza", "avatar": "https://pbs.twimg.com/profile_images/1817440734766604288/99FuIxoo_200x200.jpg", "likes": 1279, "rts": 141, "replies": 251, "views": 425937, "ts": 1792506728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1280x720/mhJ2imMl6mA4kQEF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1920x1080/2nvostHi1eUMqE7-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112552129952874496/img/X1ifILIq6yhlSaGJ.jpg", "dur": 109}], "quote": null, "reply_to": null}, {"id": "2112566864840917331", "url": "https://x.com/aibytekat/status/2112566864840917331", "text": "POV: you’re explaining your project to a new agent for the 47th time.\n\nMeanwhile Beacon, who already knows everything we tried 👇", "name": "Katyayani Shukla", "handle": "aibytekat", "avatar": "https://pbs.twimg.com/profile_images/1968767882776469504/qN_Wuv_4_200x200.jpg", "likes": 181, "rts": 83, "replies": 21, "views": 107006, "ts": 1792510164, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112565790012792832/vid/avc1/1280x720/veIESh221UPl0Dlq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112565790012792832/vid/avc1/1920x1080/EP9oCvIx6fY47edA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112565790012792832/img/h2e8A04cWGfc5OJz.jpg", "dur": 12}], "quote": {"id": "2112552451547001218", "url": "https://x.com/jqdsouza/status/2112552451547001218", "text": "We’re betting our $5.5M seed round that the next leap in AI coding won’t come from OpenAI or Anthropic.\n\nIt’ll come from a new feedback loop that learns from you.\n\nIntroducing Beacon: open-source, self-improving memory for coding agents.\n\nYour sessions capture how you debug and solve problems. Today, that context gets lost and you have to re-explain things every time you switch tools.\n\nBeacon continuously distills your sessions into reusable skills across Claude Code, Cursor, Codex, and 20+ harnesses, so your next agent can learn from the last.\n\nBeacon is free and OSS 🌟 http://github.com/Asymptote-Labs/agent-beacon\n\nWhy should the frontier labs be the only ones winning with your sessions?\n\nYou already did the work. Now let your coding agents learn from you.", "name": "Justin D'Souza", "handle": "jqdsouza", "avatar": "https://pbs.twimg.com/profile_images/1817440734766604288/99FuIxoo_200x200.jpg", "likes": 1279, "rts": 141, "replies": 251, "views": 425836, "ts": 1792506728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1280x720/mhJ2imMl6mA4kQEF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1920x1080/2nvostHi1eUMqE7-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112552129952874496/img/X1ifILIq6yhlSaGJ.jpg", "dur": 109}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792527238, "post_ids": ["2112552451547001218", "2112566864840917331"]}]);